import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_solution(n, divisors):
    tau_n = len(divisors)

    if tau_n < 5:
        return None # Must have at least 5 divisors

    # a = d2, b = d3, c = d5
    # Since divisors is sorted and starts with d1=1, 
    # d2 is at index 1, d3 at index 2, d5 at index 4.
    if len(divisors) < 5:
        return None # Should be caught by tau_n < 5, but safer check

    a = divisors[1]
    b = divisors[2]
    c = divisors[4]

    # Check the simplified equation: n = ab + ac + bc
    required_n = a * b + a * c + b * c

    if required_n == n:
        return tau_n
    else:
        return None

# Target tau values
target_taus = {7, 8, 9, 10}
MAX_N = 500
successful_taus = set()

print(f"Starting search up to N = {MAX_N}...")

for n in range(1, MAX_N + 1):
    # Optimization: only check numbers n that could potentially have the target tau values
    # For N <= 500, we check all of them since the computation is fast enough.

    divisors = get_divisors(n)
    tau_n = len(divisors)

    if tau_n in target_taus:
        result_tau = check_solution(n, divisors)
        if result_tau is not None:
            successful_taus.add(result_tau)
            print(f"Found solution for N={n} with tau(n)={result_tau}")

print("\nSearch complete.")
print("Successful tau values found:", list(successful_taus))
